import subprocess
import shutil
import os
def task_func(script_path: str, temp_dir: str) -> str:
    if not isinstance(script_path, str):
        raise TypeError("Invalid script path type")
    elif script_path == "" or not os.path.exists(script_path):
        raise OSError("Invalid script path")

    if not os.path.exists(temp_dir):
        os.makedirs(temp_dir)

    script_name = os.path.basename(script_path)
    temp_script_path = os.path.join(temp_dir, script_name)
    shutil.copy(script_path, temp_script_path)

    os.chdir(temp_dir)

    result = subprocess.run(['python', script_name], capture_output=True)

    if result.returncode == 0:
        return "Script executed successfully!"
    else:
        return "Script execution failed!"

import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str):
        raise TypeError("Invalid r_script_path type")
    elif not isinstance(output_path, str):
        raise TypeError("Invalid output_path type")
    elif not isinstance(duration, int):
        raise TypeError("Invalid duration type")
    elif r_script_path == "" or not os.path.exists(r_script_path):
        raise OSError("Invalid r_script_path")

    subprocess.Popen(['Rscript', r_script_path], shell=True)
    start_time = time.time()

    while time.time() - start_time < duration:
        if os.path.exists(output_path):
            return (True, 'File generated successfully within the specified duration.')

    return (False, 'File not generated within the specified duration.')

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range)
    results = {}
    for ip in network:
        try:
            response = subprocess.run(['ping', '-c', '1', str(ip)], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            results[str(ip)] = response.returncode == 0
        except subprocess.CalledProcessError as e:
            raise subprocess.CalledProcessError(returncode=e.returncode, cmd=e.cmd, output=e.output, stderr=e.stderr)
    return results

